    storage.max_intermediate_rows = Some(1);
    let engine = CypherEngine::new(storage);
    let error = engine
        .execute(
            "MATCH (a:Entity)-[:KNOWS]->(b:Person) WHERE a.entity_id = $id RETURN b",
            &ParameterMap::from([("id".to_string(), ScalarValue::String("a".into()))]),
