    let storage = fixture();
    let engine = CypherEngine::new(storage.clone());
    let prepared = engine
        .prepare(
            "MATCH (n:Entity) WHERE n.created_at STARTS WITH '2026' \
             RETURN n.id AS id ORDER BY n.created_at DESC, n.id SKIP 1 LIMIT 2",
            &ParameterMap::new(),
        )
        .expect("prepare skip window");
