fn a_narrow_range_beats_the_tenant_and_the_label() {
    let (parameters, lists) = corpus_parameters();
    let prepared = prepare(CORPUS[2], &parameters, &lists, &example_scope());
    let plan = access(&prepared.physical);
    let GraphPhysicalPlan::VertexPropertyRangeSeek {
        property,
        lower,
        upper,
        estimated_rows,
        read_limit,
        fallback,
        ..
    } = plan
    else {
        panic!("expected a range seek, got {plan:?}");
    };
    assert_eq!(property.as_str(), "created_at");
    assert_eq!(
        lower.as_ref().map(|(value, inclusive)| (&value.value, *inclusive)),
        Some((&ScalarValue::Integer(499), true))
    );
    assert!(upper.is_none());
    // One day of 500: 1/500 of 50,000 entries.
    assert_eq!(*estimated_rows, 100);
    assert_eq!(*read_limit, 1_000);
    // The fallback is the plan chosen without statistics.
    assert!(
        matches!(fallback.as_ref(), GraphPhysicalPlan::VertexPropertySeek { property, .. } if property.as_str() == "tenant_id"),
        "{fallback:?}"
    );
    // The whole predicate still sits above the seek.
    let GraphPhysicalPlan::Project { input, .. } = &prepared.physical else {
        panic!("project root");
    };
    let GraphPhysicalPlan::Filter { predicate, .. } = input.as_ref() else {
        panic!("filter over the seek");
    };
    let rendered = prepared.explain();
    assert!(rendered.contains("(s.created_at >= $since)"), "{rendered}");
    assert!(matches!(predicate, hydradb_cypher_engine::PhysicalExpression::Binary { .. }));
}

